/* From Uiverse.io by Jerome-W-90  - Website: https://codepen.io/havardob/pen/mdPoYmY - Name: havardob - Tags: animation, action, form, image, transition */
.__UIV_SCOPE__ .modal {
  width: 90%;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
  margin-top: 10px;
  margin-bottom: 10px;
  background-color: #fff;
  border-radius: 0.5rem;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
}

.__UIV_SCOPE__ .modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 1.5rem 1.5rem 1rem;
}

.__UIV_SCOPE__ .logo-circle {
  width: 3.5rem;
  height: 3.5rem;
  display: flex;
  justify-content: center;
  align-items: center;
  border-radius: 50%;
  background-color: #e9e5ff;
  fill: #1cc972;
}

.__UIV_SCOPE__ .btn-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 2.25rem;
  height: 2.25rem;
  border-radius: 0.25rem;
  border: none;
  background-color: transparent;
  cursor: pointer;
}

.__UIV_SCOPE__ .btn-close:hover,
.__UIV_SCOPE__ .btn-close:focus {
  background-color: #e9e5ff;
}

.__UIV_SCOPE__ .modal-body {
  padding: 1rem 1.5rem;
}

.__UIV_SCOPE__ .modal-title {
  font-weight: 700;
}

.__UIV_SCOPE__ .modal-description {
  color: #6a6b76;
}

.__UIV_SCOPE__ .upload-area {
  margin-top: 1.25rem;
  background-color: transparent;
  padding: 3rem;
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: center;
  border: 1px dashed #6a6b76;
}

.__UIV_SCOPE__ .upload-area:hover,
.__UIV_SCOPE__ .upload-area:focus {
  cursor: pointer;
  border: 1px solid #6a6b76;
}

.__UIV_SCOPE__ .upload-area:hover .upload-area-icon,
.__UIV_SCOPE__ .upload-area:focus .upload-area-icon {
  transform: scale(1.3);
  transition-duration: 0.3s;
}

.__UIV_SCOPE__ .upload-area-icon {
  display: block;
  width: 2.25rem;
  height: 2.25rem;
  fill: #1cc972;
}

.__UIV_SCOPE__ .upload-area-title {
  margin-top: 1rem;
  display: block;
  font-weight: 700;
  color: #0d0f21;
}

.__UIV_SCOPE__ .upload-area-description {
  display: block;
  color: #6a6b76;
}

.__UIV_SCOPE__ .upload-area-description strong {
  color: #1cc972;
  font-weight: 700;
}

.__UIV_SCOPE__ .modal-footer {
  padding: 1rem 1.5rem 1.5rem;
  display: flex;
  justify-content: flex-end;
}

.__UIV_SCOPE__ .modal-footer [class*="btn-"] {
  margin-left: 0.75rem;
}

.__UIV_SCOPE__ .btn-secondary,
.__UIV_SCOPE__ .btn-primary {
  padding: 0.5rem 1rem;
  font-weight: 500;
  border: 2px solid #e5e5e5;
  border-radius: 0.25rem;
  background-color: transparent;
  cursor: pointer;
}

.__UIV_SCOPE__ .btn-primary {
  color: #fff;
  background-color: #1cc972;
  border-color: #1cc972;
  cursor: pointer;
}
